int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    const char *pair = in;
    size_t pair_count = 0;

    while (pair_count < max_pairs && *pair) {
        const char *eq = strchr(pair, '=');
        if (!eq) break;
        size_t klen = (size_t)(eq - pair);
        keys_out[pair_count] = malloc(klen + 1);
        if (!keys_out[pair_count]) return -1;
        strncpy(keys_out[pair_count], pair, klen);
        keys_out[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            const char *end_quote = strchr(val_start + 1, '"');
            if (!end_quote) {
                for (size_t i = 0; i <= pair_count; i++) free(keys_out[i]);
                return -1;
            }
            size_t vlen = (size_t)(end_quote - val_start - 1);
            vals_out[pair_count] = malloc(vlen + 1);
            if (!vals_out[pair_count]) {
                for (size_t i = 0; i <= pair_count; i++) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[pair_count], val_start + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
            pair = end_quote + 1;
        } else {
            const char *space = strchr(val_start, ' ');
            if (!space) space = pair + strlen(pair);
            size_t vlen = (size_t)(space - val_start);
            vals_out[pair_count] = malloc(vlen + 1);
            if (!vals_out[pair_count]) {
                for (size_t i = 0; i <= pair_count; i++) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[pair_count], val_start, vlen);
            vals_out[pair_count][vlen] = '\0';
            pair = space + 1;
        }

        pair_count++;
    }

    return pair_count;
}

