int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    const char *pair = in;
    size_t pair_count = 0;

    while (pair && pair_count < max_pairs) {
        const char *eq = strchr(pair, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair);
        keys_out[pair_count] = (char *)malloc(klen + 1);
        if (!keys_out[pair_count]) return -1;
        strncpy(keys_out[pair_count], pair, klen);
        keys_out[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++; // Skip leading spaces

        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (!quote_end) return -1; // Missing closing quote
            size_t vlen = (size_t)(quote_end - val_start - 1);
            vals_out[pair_count] = (char *)malloc(vlen + 1);
            if (!vals_out[pair_count]) {
                free(keys_out[pair_count]);
                return -1;
            }
            strncpy(vals_out[pair_count], val_start + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
            pair = quote_end + 1;
        } else {
            const char *end = strpbrk(val_start, " \t\n");
            if (!end) end = val_start + strlen(val_start);
            size_t vlen = (size_t)(end - val_start);
            vals_out[pair_count] = (char *)malloc(vlen + 1);
            if (!vals_out[pair_count]) {
                free(keys_out[pair_count]);
                return -1;
            }
            strncpy(vals_out[pair_count], val_start, vlen);
            vals_out[pair_count][vlen] = '\0';
            pair = end;
        }

        pair_count++;
        if (*pair == ' ') pair++;
    }

    return pair_count;
}

