int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    const char *pair_start = in;
    size_t pair_count = 0;

    while (*pair_start && pair_count < max_pairs) {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair_start);
        keys[pair_count] = (char *)malloc(klen + 1);
        if (!keys[pair_count]) return -1;
        strncpy(keys[pair_count], pair_start, klen);
        keys[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            val_start++;
            const char *end_quote = strchr(val_start, '"');
            if (!end_quote) {
                for (size_t i = 0; i <= pair_count; i++) free(keys[i]);
                return -1;
            }
            size_t vlen = (size_t)(end_quote - val_start);
            vals[pair_count] = (char *)malloc(vlen + 1);
            if (!vals[pair_count]) {
                for (size_t i = 0; i <= pair_count; i++) free(keys[i]);
                return -1;
            }
            strncpy(vals[pair_count], val_start, vlen);
            vals[pair_count][vlen] = '\0';
            pair_start = end_quote + 1;
        } else {
            const char *space = strchr(val_start, ' ');
            if (!space) space = eq + strlen(eq);
            size_t vlen = (size_t)(space - val_start);
            vals[pair_count] = (char *)malloc(vlen + 1);
            if (!vals[pair_count]) {
                for (size_t i = 0; i <= pair_count; i++) free(keys[i]);
                return -1;
            }
            strncpy(vals[pair_count], val_start, vlen);
            vals[pair_count][vlen] = '\0';
            pair_start = space + 1;
        }

        pair_count++;
    }

    return pair_count;
}
